#!/usr/bin/env python3
"""Regenerate emoji.txt from Unicode's emoji-test.txt.

    python3 gen_emoji.py $(nix build --print-out-paths nixpkgs#unicode-emoji)/share/unicode/emoji/emoji-test.txt

Keeps fully-qualified emoji and leaves out skin-tone variants and the
Component group, which the picker does not list.
"""
import re
import sys
from pathlib import Path

HEADER = """\
# Emoji for the launcher's picker: one group line ("# name"), then
# "emoji<TAB>name" lines. Generated by gen_emoji.py from Unicode's
# emoji-test.txt {version} (fully-qualified, skin-tone variants left out).
#
# {copyright} Unicode and the Unicode Logo are registered
# trademarks of Unicode, Inc. in the U.S. and other countries. Distributed
# under the Unicode License v3: https://www.unicode.org/license.txt
"""


def main(source: str) -> None:
    lines = Path(source).read_text(encoding="utf-8").splitlines()
    version = next(l.split(":", 1)[1].strip() for l in lines if l.startswith("# Version:"))
    copyright_line = next(l[2:].strip() for l in lines if l.startswith("# ©"))
    out = [HEADER.format(version=version, copyright=copyright_line)]
    skip = False
    for line in lines:
        group = re.match(r"# group: (.*)", line)
        if group:
            skip = group.group(1) == "Component"
            if not skip:
                out.append("# " + group.group(1))
            continue
        if skip or line.startswith("#") or not line.strip():
            continue
        status, comment = line.split(";", 1)[1].split("#", 1)
        if status.strip() != "fully-qualified":
            continue
        emoji, _version, name = comment.strip().split(" ", 2)
        if "skin tone" not in name:
            out.append(f"{emoji}\t{name}")
    target = Path(__file__).with_name("emoji.txt")
    target.write_text("\n".join(out) + "\n", encoding="utf-8")
    print(f"{len(out) - 1} lines, {target.stat().st_size} bytes -> {target}")


if __name__ == "__main__":
    main(sys.argv[1])
